565	    /// One of the certificate's two signature algorithm descriptions, kept as
566	    /// raw slices so two copies can be compared at the DER byte level: the OID
567	    /// content (arcs in their shortest encoding) and the complete parameter
568	    /// TLV (tag, length and content), or no parameter at all. An absent
569	    /// parameter and an explicit NULL are different representations.
570	    #[derive(Clone, Copy, PartialEq, Eq)]
571	    struct SignatureAlgorithm<'a> {
572	        oid_content: &'a [u8],
573	        params: Option<&'a [u8]>,
574	    }
575	
576	    /// Parse and fully validate one signatureAlgorithm SEQUENCE, applying the
577	    /// shared AlgorithmIdentifier structure from `split_algorithm_identifier`
578	    /// and keeping the raw pieces for the byte-level comparison of the two
579	    /// copies. `loc` names which of the two copies is being checked ("outer
580	    /// signatureAlgorithm" or the copy inside tbsCertificate) and prefixes
581	    /// every error message.
582	    fn parse_signature_algorithm<'a>(
583	        alg: Tlv<'a>,
584	        loc: &str,
585	    ) -> Result<SignatureAlgorithm<'a>, String> {
586	        let (oid, params) = split_algorithm_identifier(alg.content).map_err(|e| match e {
587	            AlgIdError::OidRead(e) => format!("{loc}: {e}"),
588	            AlgIdError::OidTag(tag) => format!(
589	                "{loc}: algorithm must start with an OID (tag 0x06), got tag 0x{tag:02X}"
590	            ),
591	            AlgIdError::OidContent(e) => format!("{loc}: {e}"),
592	            AlgIdError::ParamsRead(e) => format!("{loc}: algorithm parameters: {e}"),
593	            AlgIdError::ExtraAfterParams => {
594	                format!("{loc}: extra element after the algorithm parameters")
595	            }
596	        })?;
597	        Ok(SignatureAlgorithm {
598	            oid_content: oid.content,
599	            params,
600	        })
601	    }
602	
603	    /// Describe the disagreement between the outer signatureAlgorithm and the
604	    /// copy inside tbsCertificate. Both copies parse on their own; they merely
605	    /// fail to name the same algorithm or the same parameter representation.
606	    fn mismatch_message(outer: &SignatureAlgorithm<'_>, inner: &SignatureAlgorithm<'_>) -> String {
607	        const OUTER: &str = "the outer signatureAlgorithm";
608	        const INNER: &str = "the signatureAlgorithm in tbsCertificate";
609	        if outer.oid_content != inner.oid_content {
610	            let outer_oid = parse_oid(outer.oid_content)
611	                .map(|arcs| arcs_to_string(&arcs))
612	                .unwrap_or_else(|_| "?".to_string());
613	            let inner_oid = parse_oid(inner.oid_content)
614	                .map(|arcs| arcs_to_string(&arcs))
615	                .unwrap_or_else(|_| "?".to_string());
616	            return format!(
617	                "signature algorithm mismatch: {OUTER} names OID {outer_oid}, but {INNER} \
618	                 names OID {inner_oid}"
619	            );
620	        }
621	        match (outer.params, inner.params) {
622	            (Some(outer_params), Some(inner_params)) if outer_params != inner_params => {
623	                format!(
624	                    "signature algorithm mismatch: both copies name the same algorithm OID but \
625	                     their parameters have different DER encodings ({OUTER} has {}, {INNER} has {})",
626	                    hex_of(outer_params),
627	                    hex_of(inner_params),
628	                )
629	            }
630	            (Some(_), None) => format!(
631	                "signature algorithm mismatch: {OUTER} carries parameters but {INNER} omits them \
632	                 (an absent parameter and an explicit value are different representations)"
633	            ),
634	            (None, Some(_)) => format!(
635	                "signature algorithm mismatch: {INNER} carries parameters but {OUTER} omits them \
636	                 (an absent parameter and an explicit value are different representations)"
637	            ),
638	            // PartialEq already proved the copies unequal; reaching any other
639	            // arm here would be a logic error rather than a malformed cert.
640	            _ => "signature algorithm mismatch between the two signatureAlgorithm copies"
641	                .to_string(),
642	        }
643	    }
