645	    fn hex_of(bytes: &[u8]) -> String {
646	        let mut s = String::with_capacity(bytes.len() * 2);
647	        for b in bytes {
648	            write!(s, "{b:02X}").unwrap();
649	        }
650	        s
651	    }
