711	    /// Name ::= SEQUENCE OF RDN; rendered per RFC 4514 (RDNs reversed,
712	    /// multi-valued RDNs joined with '+'). Values of known attribute types
713	    /// are emitted as real UTF-8 text (non-ASCII content preserved verbatim)
714	    /// when their tag has a text decoder; a known type carrying any other
715	    /// readable DER value (e.g. postalAddress as a SEQUENCE) keeps its short
716	    /// name and uses the '#' form carrying the value's full DER encoding in
717	    /// hex. Attributes without a known short name use their dotted OID with
718	    /// the same '#' form.
719	    ///
720	    /// Each RDN is a DER SET OF, so its complete AttributeTypeAndValue
721	    /// encodings must be sorted by their full encoding bytes (tag, then
722	    /// length, then content — the encoding, never the display name, dotted
723	    /// OID text or decoded value). The check is per RDN; it never reorders
724	    /// the members itself. `what` names the name being checked ("subject" or
725	    /// "issuer") so an ordering failure identifies it in the error message.
726	    fn format_name(name: Tlv, what: &str) -> Result<String, String> {
727	        let mut rdn_buf = name.content;
728	        let mut rdns: Vec<String> = Vec::new();
729	        while !rdn_buf.is_empty() {
730	            let (set, rest) = read_tagged(rdn_buf, TAG_SET, "RelativeDistinguishedName")?;
731	            rdn_buf = rest;
732	
733	            let mut atv_buf = set.content;
734	            let mut parts = Vec::new();
735	            // Raw full encoding (tag, length and content) of each member of
736	            // this SET OF, straight from the certificate: DER SET OF ordering
737	            // compares the complete member encodings byte for byte. Equal
738	            // encodings may legitimately repeat and stay adjacent.
739	            let mut members: Vec<&[u8]> = Vec::new();
740	            while !atv_buf.is_empty() {
741	                let atv_start = atv_buf;
742	                let (atv, rest) =
743	                    read_tagged(atv_buf, TAG_SEQUENCE, "AttributeTypeAndValue")?;
744	                atv_buf = rest;
745	                members.push(&atv_start[..atv_start.len() - atv_buf.len()]);
746	
747	                let (oid, after_oid) = read_tagged(atv.content, TAG_OID, "attribute OID")?;
748	                let (value, after_value) = read_tlv(after_oid)?;
749	                if !after_value.is_empty() {
750	                    return Err("trailing data in attribute value".to_string());
751	                }
752	
753	                let oid_arcs = parse_oid(oid.content)?;
754	
755	                // The value's own string-type rules are applied exactly once,
756	                // here, before any display decision and regardless of whether
757	                // the attribute later renders as text for a known short name
758	                // or as '#'-hex for an unknown type: a UTF8String must hold
759	                // valid UTF-8, a PrintableString must keep to its alphabet, a
760	                // BMPString must hold whole 16-bit non-surrogate characters
761	                // and a UniversalString must hold whole, in-range Unicode
762	                // code points. The hex form must never let an illegal byte or
763	                // code point through, and illegal content cannot be dropped or
764	                // replaced. An empty value stays legal. Tags without string
765	                // rules (SEQUENCE, OCTET STRING, ...) pass untouched and are
766	                // simply not text-decodable. `what` names the offending name
767	                // ("subject"/"issuer").
768	                let text = check_attribute_string(value, what)?;
769	
770	                match oid_short_name(&oid_arcs) {
771	                    Some(label) => match text {
772	                        // Supported string type: decode to escaped text.
773	                        Some(text) => parts.push(format!("{label}={}", escape_value(&text))),
774	                        // Known type but a legal value with no text decoder
775	                        // (SEQUENCE, OCTET STRING, ...): keep the short name
776	                        // and show the full original DER encoding as '#'-hex.
777	                        None => {
778	                            parts.push(format!("{label}=#{}", value_hex(after_oid, after_value)))
779	                        }
780	                    },
781	                    None => {
782	                        // Unknown attribute type: RFC 4514 requires the form
783	                        // OID=#hex, where the hex is the full DER encoding
784	                        // (tag, length and content) of the attribute value.
785	                        // The value is still a string governed by its type
786	                        // rules, already checked once above; whether it
787	                        // decoded to text never affects this hex display.
788	                        let hex = value_hex(after_oid, after_value);
789	                        parts.push(format!("{}=#{hex}", arcs_to_string(&oid_arcs)));
790	                    }
791	                }
792	            }
793	            if parts.is_empty() {
794	                return Err("empty RelativeDistinguishedName".to_string());
795	            }
796	            check_rdn_der_order(&members, what)?;
797	            rdns.push(parts.join("+"));
798	        }
799	        rdns.reverse();
800	        Ok(rdns.join(","))
801	    }
802	
803	    /// Validate one RDN as a DER SET OF: every member's complete
804	    /// AttributeTypeAndValue encoding must be less than or equal to the next
805	    /// one under ordinary byte ordering of tag, length and content. The
806	    /// comparison runs on the raw encodings only — CN/O short names, dotted
807	    /// OID text and decoded values never enter into it — and equal adjacent
808	    /// members (duplicate attributes) are allowed. The members are never
809	    /// reordered to make an unsorted input pass. `what` is "subject" or
810	    /// "issuer" and identifies the offending name in the error message.
811	    fn check_rdn_der_order(members: &[&[u8]], what: &str) -> Result<(), String> {
812	        for pair in members.windows(2) {
813	            if pair[0] > pair[1] {
814	                return Err(format!(
815	                    "{what} name: attributes of a multi-valued RelativeDistinguishedName \
816	                     are not encoded in DER SET OF order (the members must be sorted by \
817	                     their complete DER encoding bytes: tag, then length, then content)"
818	                ));
819	            }
820	        }
821	        Ok(())
822	    }
823	
824	    /// Uppercase hex of one complete value TLV, sliced straight from the
825	    /// input bytes (`around` ends at `rest`). The original tag and length
826	    /// bytes survive verbatim, including a legal long-form length; nothing is
827	    /// re-encoded and content alone is never emitted.
828	    fn value_hex(around: &[u8], rest: &[u8]) -> String {
829	        let tlv_len = around.len() - rest.len();
830	        let mut hex = String::with_capacity(tlv_len * 2);
831	        for b in &around[..tlv_len] {
832	            write!(hex, "{b:02X}").unwrap();
833	        }
834	        hex
835	    }
836	
837	    /// One OID arc (subidentifier) as an arbitrary-precision unsigned
838	    /// integer. An OID arc has no upper bound in the standard: any
839	    /// shortest-form base-128 subidentifier is legal, however many bits its
840	    /// value needs, so the arcs are kept as exact bignums rather than a
841	    /// machine integer whose range would become a false legality limit.
842	    ///
843	    /// `limbs` is little-endian base 2^32 with no trailing zero limbs; the
844	    /// empty vector is zero. Normalization is maintained by every
845	    /// constructor and mutator, so derived equality is value equality.
846	    #[derive(Clone, PartialEq, Eq)]
847	    struct Arc {
848	        limbs: Vec<u32>,
849	    }
850	
851	    impl Arc {
852	        fn from_u64(value: u64) -> Arc {
853	            let mut limbs = vec![value as u32, (value >> 32) as u32];
854	            while limbs.last() == Some(&0) {
855	                limbs.pop();
856	            }
857	            Arc { limbs }
858	        }
859	
860	        /// The value as a `u64` when it fits, else `None`. Used only where a
861	        /// small arc is required (the first subidentifier split and the
862	        /// known-attribute table); large arcs simply take the other branch.
863	        fn as_u64(&self) -> Option<u64> {
864	            match self.limbs.len() {
865	                0 => Some(0),
866	                1 => Some(self.limbs[0] as u64),
867	                2 => Some(self.limbs[0] as u64 | (self.limbs[1] as u64) << 32),
868	                _ => None,
869	            }
870	        }
871	
872	        /// self = self * 128 + add (add < 128): one base-128 digit appended
873	        /// while reading a subidentifier.
874	        fn mul_add_128(&mut self, add: u32) {
875	            let mut carry = add as u64;
876	            for limb in &mut self.limbs {
877	                let t = (*limb as u64) * 128 + carry;
878	                *limb = t as u32;
879	                carry = t >> 32;
880	            }
881	            while carry > 0 {
882	                self.limbs.push(carry as u32);
883	                carry >>= 32;
884	            }
885	        }
886	
887	        /// self = self - sub, where sub < 2^32 and self >= sub. Only used to
888	        /// peel 40/80 off the first subidentifier once it is known to be
889	        /// large enough.
890	        fn sub_u32(&mut self, sub: u32) {
891	            let mut borrow = sub as u64;
892	            for limb in &mut self.limbs {
893	                let cur = *limb as u64;
894	                if cur >= borrow {
895	                    *limb = (cur - borrow) as u32;
896	                    borrow = 0;
897	                    break;
898	                }
899	                *limb = (cur + (1u64 << 32) - borrow) as u32;
900	                borrow = 1;
901	            }
902	            debug_assert_eq!(borrow, 0, "sub_u32 underflow");
903	            while self.limbs.last() == Some(&0) {
904	                self.limbs.pop();
905	            }
906	        }
907	
908	        /// Exact decimal rendering, by repeated division by 10^9.
909	        fn to_decimal(&self) -> String {
910	            if self.limbs.is_empty() {
911	                return "0".to_string();
912	            }
913	            const CHUNK: u64 = 1_000_000_000;
914	            let mut limbs = self.limbs.clone();
915	            let mut chunks: Vec<u32> = Vec::new();
916	            while !limbs.is_empty() {
917	                let mut rem = 0u64;
918	                for limb in limbs.iter_mut().rev() {
919	                    let cur = (rem << 32) | (*limb as u64);
920	                    *limb = (cur / CHUNK) as u32;
921	                    rem = cur % CHUNK;
922	                }
923	                while limbs.last() == Some(&0) {
924	                    limbs.pop();
925	                }
926	                chunks.push(rem as u32);
927	            }
928	            let mut s = chunks.last().unwrap().to_string();
929	            for chunk in chunks.iter().rev().skip(1) {
930	                write!(s, "{chunk:09}").unwrap();
931	            }
932	            s
933	        }
934	    }
935	
936	    fn parse_oid(content: &[u8]) -> Result<Vec<Arc>, String> {
937	        if content.is_empty() {
938	            return Err("empty OID".to_string());
939	        }
940	        let mut arcs = Vec::new();
941	        // The first subidentifier encodes the first two arcs as
942	        // 40*first + second and is itself a base-128 quantity, so it can
943	        // span multiple content bytes (e.g. 2.999 encodes as 0x88 0x37) and
944	        // can exceed any machine integer width when the second arc is huge.
945	        let mut i = 0;
946	        let first = read_oid_arc(content, &mut i)?;
947	        match first.as_u64() {
948	            Some(v @ 0..=39) => {
949	                arcs.push(Arc::from_u64(0));
950	                arcs.push(Arc::from_u64(v));
951	            }
952	            Some(v @ 40..=79) => {
953	                arcs.push(Arc::from_u64(1));
954	                arcs.push(Arc::from_u64(v - 40));
955	            }
956	            _ => {
957	                // First arc 2: the second arc is the subidentifier minus 80,
958	                // kept at full precision even when it needs more than 64
959	                // bits.
960	                let mut second = first;
961	                second.sub_u32(80);
962	                arcs.push(Arc::from_u64(2));
963	                arcs.push(second);
964	            }
965	        }
966	        while i < content.len() {
967	            arcs.push(read_oid_arc(content, &mut i)?);
968	        }
969	        Ok(arcs)
970	    }
971	
972	    /// Read one base-128 subidentifier starting at `*i`. Rejects trailing
973	    /// continuation bytes and non-minimal encodings; the value itself is
974	    /// unbounded and kept exactly.
975	    fn read_oid_arc(content: &[u8], i: &mut usize) -> Result<Arc, String> {
976	        let start = *i;
977	        let mut value = Arc { limbs: Vec::new() };
978	        loop {
979	            let b = *content
980	                .get(*i)
981	                .ok_or_else(|| "truncated OID arc".to_string())?;
982	            value.mul_add_128((b & 0x7F) as u32);
983	            *i += 1;
984	            if b & 0x80 == 0 {
985	                break;
986	            }
987	        }
988	        if *i - start > 1 && content[start] == 0x80 {
989	            return Err("non-minimal OID arc encoding".to_string());
990	        }
991	        Ok(value)
992	    }
993	
994	    fn arcs_to_string(arcs: &[Arc]) -> String {
995	        arcs.iter()
996	            .map(Arc::to_decimal)
997	            .collect::<Vec<_>>()
998	            .join(".")
999	    }
