1001	    fn oid_short_name(arcs: &[Arc]) -> Option<&'static str> {
1002	        // The known names all live far below 2^64; any arc that does not fit
1003	        // a u64 cannot match, which falls out of the conversion for free.
1004	        let small: Option<Vec<u64>> = arcs.iter().map(Arc::as_u64).collect();
1005	        // X.520 / X.521 (2.5.4.*) and the commonly used LDAP/PKCS names.
1006	        let name = match small.as_deref() {
1007	            Some([2, 5, 4, 3]) => "CN",
1008	            Some([2, 5, 4, 4]) => "SN",
1009	            Some([2, 5, 4, 5]) => "serialNumber",
1010	            Some([2, 5, 4, 6]) => "C",
1011	            Some([2, 5, 4, 7]) => "L",
1012	            Some([2, 5, 4, 8]) => "ST",
1013	            Some([2, 5, 4, 9]) => "STREET",
1014	            Some([2, 5, 4, 10]) => "O",
1015	            Some([2, 5, 4, 11]) => "OU",
1016	            Some([2, 5, 4, 12]) => "title",
1017	            Some([2, 5, 4, 17]) => "postalAddress",
1018	            Some([2, 5, 4, 18]) => "postalCode",
1019	            Some([2, 5, 4, 20]) => "telephoneNumber",
1020	            Some([2, 5, 4, 42]) => "givenName",
1021	            Some([2, 5, 4, 43]) => "initials",
1022	            Some([2, 5, 4, 44]) => "generationQualifier",
1023	            Some([2, 5, 4, 46]) => "dnQualifier",
1024	            Some([2, 5, 4, 65]) => "pseudonym",
1025	            Some([0, 9, 2342, 19200300, 100, 1, 1]) => "UID",
1026	            Some([0, 9, 2342, 19200300, 100, 1, 25]) => "DC",
1027	            Some([1, 2, 840, 113549, 1, 9, 1]) => "emailAddress",
1028	            _ => return None,
1029	        };
1030	        Some(name)
1031	    }
