1033	    /// Whether every byte belongs to the RFC 5280 PrintableString alphabet:
1034	    /// A-Z, a-z, 0-9, space, and ' ( ) + , - . / : = ?. Every other byte
1035	    /// (including @, _, tabs, newlines, NUL and 0x80..=0xFF) is illegal.
1036	    /// An empty value passes, preserving the existing acceptance of empty
1037	    /// contents.
1038	    fn is_printable_string(content: &[u8]) -> bool {
1039	        content.iter().all(|&b| matches!(
1040	            b,
1041	            b'A'..=b'Z'
1042	                | b'a'..=b'z'
1043	                | b'0'..=b'9'
1044	                | b' '
1045	                | b'\''
1046	                | b'('
1047	                | b')'
1048	                | b'+'
1049	                | b','
1050	                | b'-'
1051	                | b'.'
1052	                | b'/'
1053	                | b':'
1054	                | b'='
1055	                | b'?'
1056	        ))
1057	    }
1058	
1059	    /// Validate BMPString content and decode it to UTF-8 text in one pass: an
1060	    /// even number of bytes read as big-endian 16-bit characters, each of
1061	    /// which must be a Basic Multilingual Plane code point
1062	    /// (U+0000..=U+FFFF) and never a UTF-16 surrogate (U+D800..=U+DFFF).
1063	    /// Surrogates are not characters, so a lone high or low surrogate is
1064	    /// corrupt, and so is an adjacent pair that UTF-16 rules would combine
1065	    /// into an astral-plane character — the pair must not be merged and
1066	    /// displayed. An illegal value fails the whole certificate; bytes are
1067	    /// never dropped or replaced to salvage it. Empty content stays legal,
1068	    /// preserving the existing acceptance of empty values. `what` names the
1069	    /// name being checked ("subject"/"issuer") so the error identifies the
1070	    /// offending name.
1071	    fn decode_bmp_string(content: &[u8], what: &str) -> Result<String, String> {
1072	        if content.len() % 2 != 0 {
1073	            return Err(format!(
1074	                "{what} name: BMPString attribute value has an odd length of {} byte(s) \
1075	                 (the content must be a sequence of 16-bit characters)",
1076	                content.len()
1077	            ));
1078	        }
1079	        // A BMPString character is one big-endian 16-bit BMP code point, never
1080	        // a UTF-16 surrogate: surrogate pairs must not be merged into
1081	        // astral-plane characters.
1082	        let mut s = String::with_capacity(content.len() / 2);
1083	        for pair in content.chunks_exact(2) {
1084	            let unit = u16::from_be_bytes([pair[0], pair[1]]);
1085	            if (0xD800..=0xDFFF).contains(&unit) {
1086	                return Err(format!(
1087	                    "{what} name: BMPString attribute value contains the surrogate code \
1088	                     point U+{unit:04X}, which is not a legal character (U+D800..=U+DFFF \
1089	                     are not characters and cannot appear, alone or in pairs)"
1090	                ));
1091	            }
1092	            // Not a surrogate, so every 16-bit unit is a valid scalar value.
1093	            s.push(char::from_u32(unit as u32).unwrap());
1094	        }
1095	        Ok(s)
1096	    }
1097	
1098	    /// Validate UniversalString content and decode it to UTF-8 text in one
1099	    /// pass: the bytes must form whole big-endian 32-bit Unicode code points,
1100	    /// so the length must be a multiple of four, and every code point must lie
1101	    /// in U+0000..=U+10FFFF and never be a UTF-16 surrogate
1102	    /// (U+D800..=U+DFFF). A trailing incomplete unit, a lone surrogate (or a
1103	    /// pair that UTF-16 rules would combine), or a value above the Unicode
1104	    /// ceiling is corrupt; the whole certificate fails and no unit is dropped,
1105	    /// replaced or merely hex-displayed to salvage it. Empty content stays
1106	    /// legal, preserving the existing acceptance of empty values. `what` names
1107	    /// the name being checked ("subject"/"issuer") so the error identifies the
1108	    /// offending name.
1109	    fn decode_universal_string(content: &[u8], what: &str) -> Result<String, String> {
1110	        if content.len() % 4 != 0 {
1111	            return Err(format!(
1112	                "{what} name: UniversalString attribute value has a length of {} byte(s), \
1113	                 which is not a multiple of four (the content must be a sequence of \
1114	                 big-endian 32-bit Unicode code points)",
1115	                content.len()
1116	            ));
1117	        }
1118	        let mut s = String::new();
1119	        for unit in content.chunks_exact(4) {
1120	            let cp = u32::from_be_bytes([unit[0], unit[1], unit[2], unit[3]]);
1121	            if (0xD800..=0xDFFF).contains(&cp) {
1122	                return Err(format!(
1123	                    "{what} name: UniversalString attribute value contains the surrogate code \
1124	                     point U+{cp:04X}, which is not a legal character (U+D800..=U+DFFF are \
1125	                     not characters and cannot appear, alone or in pairs)"
1126	                ));
1127	            }
1128	            if cp > 0x10FFFF {
1129	                return Err(format!(
1130	                    "{what} name: UniversalString attribute value contains the code point \
1131	                     U+{cp:04X}, which is above the Unicode maximum U+10FFFF"
1132	                ));
1133	            }
1134	            s.push(char::from_u32(cp).unwrap());
1135	        }
1136	        Ok(s)
1137	    }
1138	
1139	    /// Validate one name attribute value against the rules of its own string
1140	    /// type and, when it is a supported string type, decode it to UTF-8 text.
1141	    ///
1142	    /// This is the single place that owns each supported string type's rules
1143	    /// (valid UTF-8, the PrintableString alphabet, whole BMP characters
1144	    /// without surrogates, whole in-range UniversalString code points) and the
1145	    /// single place that decodes them, so the legality check and the text
1146	    /// decoding can never drift apart. It runs once per attribute, before any
1147	    /// display decision and regardless of whether the attribute later renders
1148	    /// as text for a known short name or as '#'-hex for an unknown type:
1149	    /// showing a value as hex must never let an illegal byte or code point
1150	    /// through, and illegal content cannot be dropped or replaced.
1151	    ///
1152	    /// Returns `Ok(Some(text))` for a supported, valid string type, and
1153	    /// `Ok(None)` for any other tag (a legal DER value with no text decoder —
1154	    /// a SEQUENCE, OCTET STRING, … — which the caller renders as '#'-hex). An
1155	    /// empty string value is legal and decodes to empty text. `what` names the
1156	    /// name being checked ("subject"/"issuer") so an error identifies it.
1157	    fn check_attribute_string(value: Tlv, what: &str) -> Result<Option<String>, String> {
1158	        let content = value.content;
1159	        let text = match value.tag {
1160	            TAG_UTF8_STRING => std::str::from_utf8(content)
1161	                .map_err(|_| "invalid UTF-8 in UTF8String".to_string())?
1162	                .to_string(),
1163	            TAG_PRINTABLE_STRING => {
1164	                if !is_printable_string(content) {
1165	                    return Err(format!(
1166	                        "{what} name: PrintableString attribute value contains an illegal \
1167	                         character (only A-Z, a-z, 0-9, space and ' ( ) + , - . / : = ? are \
1168	                         allowed)"
1169	                    ));
1170	                }
1171	                // ASCII-family: after the alphabet check every byte is also
1172	                // its Unicode code point.
1173	                content.iter().map(|&b| b as char).collect()
1174	            }
1175	            // NumericString (0x12), IA5String (0x16) and VisibleString (0x1A)
1176	            // are ASCII-family strings: every byte is also its Unicode code
1177	            // point and they carry no extra character rule here.
1178	            0x12 | 0x16 | 0x1A => content.iter().map(|&b| b as char).collect(),
1179	            // T.61/TeletexString (0x14) and GeneralString (0x1B) are
1180	            // conventionally treated as Latin-1 here: the byte value is the
1181	            // code point and they carry no extra character rule here.
1182	            0x14 | 0x1B => content.iter().map(|&b| b as char).collect(),
1183	            TAG_BMP_STRING => decode_bmp_string(content, what)?,
1184	            TAG_UNIVERSAL_STRING => decode_universal_string(content, what)?,
1185	            // Any other readable DER value (SEQUENCE, OCTET STRING, ...) is a
1186	            // legal non-text attribute value: it has no string rule to apply
1187	            // and no text decoder, so it is rendered from its original DER as
1188	            // '#'-hex.
1189	            _ => return Ok(None),
1190	        };
1191	        Ok(Some(text))
1192	    }
1193	
1194	    /// RFC 4514 value escaping; everything above the ASCII control range
1195	    /// (including CJK text) passes through unchanged.
1196	    fn escape_value(value: &str) -> String {
1197	        let mut out = String::with_capacity(value.len());
1198	        let last = value.chars().count().saturating_sub(1);
1199	        for (i, c) in value.chars().enumerate() {
1200	            let at_edge = i == 0 || i == last;
1201	            let needs_backslash = matches!(c, ',' | '+' | '"' | '\\' | '<' | '>' | ';')
1202	                || (at_edge && (c == ' ' || c == '#'));
1203	            if needs_backslash {
1204	                out.push('\\');
1205	                out.push(c);
1206	            } else if ('\0'..='\x1F').contains(&c) || c == '\x7F' {
1207	                let mut buf = [0u8; 4];
1208	                let b = c.encode_utf8(&mut buf).as_bytes()[0];
1209	                write!(out, "\\{b:02X}").unwrap();
1210	            } else {
1211	                out.push(c);
1212	            }
1213	        }
1214	        out
1215	    }
1216	
1217	    fn format_time(tlv: Tlv) -> Result<String, String> {
1218	        let (y, mo, d, h, mi, se) = match tlv.tag {
1219	            TAG_UTC_TIME => {
1220	                let c = tlv.content;
1221	                if c.len() != 13 || c[12] != b'Z' {
1222	                    return Err("UTCTime must be YYMMDDHHMMSSZ".to_string());
1223	                }
1224	                let digits = &c[..12];
1225	                if !digits.iter().all(|b| b.is_ascii_digit()) {
1226	                    return Err("non-numeric UTCTime".to_string());
1227	                }
1228	                let n = |a: usize, b: usize| -> u32 {
1229	                    digits[a..=b].iter().fold(0, |acc, x| acc * 10 + (x - b'0') as u32)
1230	                };
1231	                let yy = n(0, 1);
1232	                let year = if yy < 50 { 2000 + yy } else { 1900 + yy };
1233	                (year as i32, n(2, 3), n(4, 5), n(6, 7), n(8, 9), n(10, 11))
1234	            }
1235	            TAG_GENERALIZED_TIME => {
1236	                let c = tlv.content;
1237	                if c.len() != 15 || c[14] != b'Z' {
1238	                    return Err(
1239	                        "GeneralizedTime must be YYYYMMDDHHMMSSZ in UTC".to_string()
1240	                    );
1241	                }
1242	                let digits = &c[..14];
1243	                if !digits.iter().all(|b| b.is_ascii_digit()) {
1244	                    return Err("non-numeric GeneralizedTime".to_string());
1245	                }
1246	                let n = |a: usize, b: usize| -> u32 {
1247	                    digits[a..=b].iter().fold(0, |acc, x| acc * 10 + (x - b'0') as u32)
1248	                };
1249	                (n(0, 3) as i32, n(4, 5), n(6, 7), n(8, 9), n(10, 11), n(12, 13))
1250	            }
1251	            other => return Err(format!("invalid time tag 0x{other:02X}")),
1252	        };
1253	        validate_datetime(y, mo, d, h, mi, se)?;
1254	        Ok(format!("{y:04}-{mo:02}-{d:02}T{h:02}:{mi:02}:{se:02}Z"))
1255	    }
1256	
1257	    fn validate_datetime(
1258	        year: i32,
1259	        month: u32,
1260	        day: u32,
1261	        hour: u32,
1262	        minute: u32,
1263	        second: u32,
1264	    ) -> Result<(), String> {
1265	        if !(1..=12).contains(&month) {
1266	            return Err("invalid month in certificate time".to_string());
1267	        }
1268	        if hour > 23 || minute > 59 || second > 59 {
1269	            return Err("invalid time of day in certificate time".to_string());
1270	        }
1271	        let leap = year % 4 == 0 && (year % 100 != 0 || year % 400 == 0);
1272	        let days = [31, if leap { 29 } else { 28 }, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
1273	        if day < 1 || day > days[(month - 1) as usize] {
1274	            return Err("invalid day in certificate time".to_string());
1275	        }
1276	        Ok(())
1277	    }
1278	}
