which python3 && python3 - <<'EOF'
import subprocess, tempfile, os

def tlv(tag, content):
    n = len(content)
    if n < 0x80:
        ln = bytes([n])
    else:
        b = n.to_bytes((n.bit_length()+7)//8, 'big')
        ln = bytes([0x80|len(b)]) + b
    return bytes([tag]) + ln + content

def seq(c): return tlv(0x30, c)
def oid(arcs):
    body = bytes([arcs[0]*40+arcs[1]]) if arcs[0]*40+arcs[1] < 128 else None
    v = arcs[0]*40+arcs[1]
    out = [v % 128]; v //= 128
    while v: out.append(0x80 | v%128); v//=128
    out.reverse()
    for a in arcs[2:]:
        digits=[a%128]; a//=128
        while a: digits.append(0x80|a%128); a//=128
        digits.reverse(); out+=digits
    return tlv(0x06, bytes(out))

def atv(arcs, val): return seq(oid(arcs)+val)
def name(rdns): return seq(b''.join(rdns))
def rdn(atvs): return tlv(0x31, b''.join(atvs))
CN=[2,5,4,3]
sigalg = seq(oid([1,2,840,113549,1,1,11])+tlv(0x05,b''))
serial = tlv(0x02, bytes.fromhex('0E8A4C2F9B17D603'))
validity = seq(tlv(0x17,b'260115093000Z')+tlv(0x17,b'270115093000Z'))
spki = seq(seq(oid([1,2,840,113549,1,1,1])+tlv(0x05,b''))+tlv(0x03,b'\x00\x01\x00'))
issuer = name([rdn([atv(CN, tlv(0x0C, b'Test CA'))])])

def cert(subject_bytes):
    tbs = seq(serial+sigalg+issuer+validity+subject_bytes+spki)
    return seq(tbs+sigalg+tlv(0x03,b'\x00'))

cases = {
  'bad-ia5-subject (CN contains 0xFF)': name([rdn([atv(CN, tlv(0x16, b'a\xffb'))])]),
  'bad-ia5-utf8ish (CN contains E4 B8 AD)': name([rdn([atv(CN, tlv(0x16, '中'.encode()))])]),
  'bad-ia5-unknown-oid': name([rdn([atv([1,2,3,4], tlv(0x16, b'a\x80'))])]),
  'good-ia5-tab': name([rdn([atv(CN, tlv(0x16, b'a\tb'))])]),
  'good-utf8-cjk': name([rdn([atv(CN, tlv(0x0C, '中'.encode()))])]),
}
binpath = './target/debug/chainview'
for label, subj in cases.items():
    f = tempfile.NamedTemporaryFile(delete=False, suffix='.der')
    f.write(cert(subj)); f.close()
    p = subprocess.run([binpath,'inspect',f.name], capture_output=True)
    os.unlink(f.name)
    print(f'== {label}: exit={p.returncode}')
    if p.stdout: print('STDOUT:', p.stdout.decode('utf-8', 'replace').rstrip().splitlines()[:1])
    if p.stderr: print('STDERR:', p.stderr.decode('utf-8','replace').rstrip())
EOF

